  function openBoard() {
    const Q = [["What is turning the water grey?", ["Fertiliser off the lawns", "Concrete washout, pumped in at night", "‘Natural pond turnover’", "Geese"], 1, "Concrete washout from the pit, on a timer, down a hose, into the east bank.", "Mallory would like the word ‘geese’ struck from the record."],
      ["Why is the pond dropping?", ["A dry summer", "Somebody opened the drain", "The creek is blocked", "Agnes drank it"], 1, "All four wheels on the outlet riser were opened with a wrench and tagged ‘do not close.’", "Agnes has heard that one. Agnes did not laugh then either."],
      ["Who needs this pond to fail?", ["The girl with the test tubes", "The county", "The builder: a failed pond gets them a permit for the vault", "Big Lou"], 2, "The Serenity Amenity Upgrade can only be approved if the pond flunks its water-quality review.", "Lou would like a word."]];
    openSheet(`<h2>Lay it out for Lou</h2><p class="sub">Five facts, three questions. Tap the answer the evidence supports.</p>` + Q.map((q, i) => `<div class="clueq" data-q="${i}"><div class="ask">${q[0]}</div><div class="opts">${q[1].map((o, j) => `<button data-o="${j}">${o}</button>`).join('')}</div><div class="ans">${q[3]}</div></div>`).join(''));
    let n = 0; $('#sheetCard').querySelectorAll('.clueq button').forEach(b => b.onclick = () => { const el = b.closest('.clueq'), q = Q[+el.dataset.q]; if (+b.dataset.o === q[2]) { el.classList.add('ok'); sfx.pick(); if (++n === 3) { setFlag('solved'); setTimeout(() => { closeSheet(true); say(D.reveal); }, 900); } } else { el.classList.remove('shake'); void el.offsetWidth; el.classList.add('shake'); sfx.bad(); toast(q[4]); } });
  }
  function openWheels() {
    let got = 0; const keys = ['red', 'yellow', 'blue', 'green'], mine = canUse('dive');
    openSheet(`<h2>${mine ? 'The outlet wheels' : 'Call it down to Agnes'}</h2><p class="sub">${mine ? 'Four wheels, ganged. They close in one order only. Somebody up top has the card.' : 'Agnes is at the wheels with her jaw set. Tell her which to turn, in order.'}</p><div class="wheels">${keys.map(k => `<button class="wheel" data-k="${k}" style="background:${TAGS[k][0]}" aria-label="${TAGS[k][2]}">${TAGS[k][1]}</button>`).join('')}</div><p class="sub" id="whSay">${flag('card') || !isPlayed('frog') ? '' : 'Tad can get at the card in the breaker box.'}</p>`);
    $('#sheetCard').querySelectorAll('.wheel').forEach(b => b.onclick = () => { if (b.classList.contains('done')) return; if (b.dataset.k === R.order[got]) { b.classList.add('done'); sfx.turn(); got++; if (got === 4) { setFlag('shut'); setVal('water', 0); sfx.ok(); setTimeout(() => { closeSheet(true); say(D.shut); }, 700); } }
      else { got = 0; sfx.clank(); $('#sheetCard').querySelectorAll('.wheel').forEach(w => w.classList.remove('done')); $('#whSay').textContent = pick(["All four spin back open. The pond makes a rude noise.", "Wrong. The wheels unwind. Somewhere, a catfish laughs.", "They reopen. Agnes says nothing, at length."]); } });
  }
